import pygame
import random
import sys

WIDTH, HEIGHT = 640, 720
FPS = 60

WHITE = (240, 240, 240)
BLACK = (10, 10, 20)
GREEN = (80, 220, 100)
RED = (230, 80, 80)
CYAN = (80, 200, 230)
YELLOW = (240, 220, 80)

PLAYER_SPEED = 5
BULLET_SPEED = 8
ALIEN_BULLET_SPEED = 4
ALIEN_ROWS = 4
ALIEN_COLS = 8
ALIEN_DESCEND = 20
START_LIVES = 3


class Player:
    def __init__(self):
        self.w, self.h = 48, 20
        self.x = WIDTH // 2 - self.w // 2
        self.y = HEIGHT - 60
        self.cooldown = 0

    def rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)

    def update(self, keys):
        if keys[pygame.K_LEFT] or keys[pygame.K_a]:
            self.x -= PLAYER_SPEED
        if keys[pygame.K_RIGHT] or keys[pygame.K_d]:
            self.x += PLAYER_SPEED
        self.x = max(0, min(WIDTH - self.w, self.x))
        if self.cooldown > 0:
            self.cooldown -= 1

    def shoot(self, bullets):
        if self.cooldown <= 0:
            bullets.append(pygame.Rect(self.x + self.w // 2 - 2, self.y - 12, 4, 12))
            self.cooldown = 18


class Alien:
    def __init__(self, col, row):
        self.w, self.h = 36, 24
        self.x = 60 + col * 60
        self.y = 60 + row * 50
        self.points = (ALIEN_ROWS - row) * 10

    def rect(self):
        return pygame.Rect(self.x, self.y, self.w, self.h)


class Game:
    def __init__(self):
        pygame.init()
        self.screen = pygame.display.set_mode((WIDTH, HEIGHT))
        pygame.display.set_caption("Space Invaders")
        self.clock = pygame.time.Clock()
        self.font = pygame.font.SysFont(None, 28)
        self.big_font = pygame.font.SysFont(None, 56)
        self.reset()

    def reset(self):
        self.player = Player()
        self.bullets = []
        self.alien_bullets = []
        self.aliens = [Alien(c, r) for r in range(ALIEN_ROWS) for c in range(ALIEN_COLS)]
        self.alien_dir = 1
        self.alien_timer = 0.0
        self.score = 0
        self.lives = START_LIVES
        self.state = "play"

    def alien_speed(self):
        return 0.5 + (ALIEN_ROWS * ALIEN_COLS - len(self.aliens)) * 0.03

    def update(self):
        if self.state != "play":
            return
        keys = pygame.key.get_pressed()
        self.player.update(keys)
        if keys[pygame.K_SPACE]:
            self.player.shoot(self.bullets)

        for b in self.bullets[:]:
            b.y -= BULLET_SPEED
            if b.y < -12:
                self.bullets.remove(b)
                continue
            for a in self.aliens[:]:
                if b.colliderect(a.rect()):
                    self.aliens.remove(a)
                    self.score += a.points
                    if b in self.bullets:
                        self.bullets.remove(b)
                    break

        self.alien_timer += self.alien_speed()
        step = int(self.alien_timer)
        if step >= 1 and self.aliens:
            self.alien_timer -= step
            dx = self.alien_dir * step * 6
            min_x = min(a.x for a in self.aliens)
            max_x = max(a.x + a.w for a in self.aliens)
            descend = False
            if max_x + dx >= WIDTH - 10 or min_x + dx <= 10:
                self.alien_dir *= -1
                dx = self.alien_dir * step * 6
                descend = True
            for a in self.aliens:
                a.x += dx
                if descend:
                    a.y += ALIEN_DESCEND
            if max(a.y + a.h for a in self.aliens) >= self.player.y:
                self.state = "lose"

        if self.aliens and random.random() < 0.02:
            shooter = random.choice(self.aliens)
            self.alien_bullets.append(
                pygame.Rect(shooter.x + shooter.w // 2 - 2, shooter.y + shooter.h, 4, 10)
            )

        for b in self.alien_bullets[:]:
            b.y += ALIEN_BULLET_SPEED
            if b.y > HEIGHT:
                self.alien_bullets.remove(b)
                continue
            if b.colliderect(self.player.rect()):
                self.alien_bullets.remove(b)
                self.lives -= 1
                if self.lives <= 0:
                    self.state = "lose"

        if not self.aliens:
            self.state = "win"

    def draw_alien(self, a):
        r = a.rect()
        pygame.draw.rect(self.screen, GREEN, (r.x + 4, r.y, r.w - 8, r.h))
        pygame.draw.rect(self.screen, GREEN, (r.x, r.y + 6, r.w, r.h - 10))
        pygame.draw.rect(self.screen, BLACK, (r.x + 8, r.y + 8, 6, 6))
        pygame.draw.rect(self.screen, BLACK, (r.x + r.w - 14, r.y + 8, 6, 6))

    def draw(self):
        self.screen.fill(BLACK)
        p = self.player.rect()
        pygame.draw.polygon(self.screen, CYAN, [
            (p.x + p.w // 2, p.y),
            (p.x + p.w, p.y + p.h),
            (p.x + p.w // 2, p.y + p.h - 6),
            (p.x, p.y + p.h),
        ])
        for b in self.bullets:
            pygame.draw.rect(self.screen, YELLOW, b)
        for b in self.alien_bullets:
            pygame.draw.rect(self.screen, RED, b)
        for a in self.aliens:
            self.draw_alien(a)
        hud = self.font.render(f"Score: {self.score}   Lives: {self.lives}", True, WHITE)
        self.screen.blit(hud, (10, 10))
        if self.state != "play":
            msg = "YOU WIN!" if self.state == "win" else "GAME OVER"
            color = YELLOW if self.state == "win" else RED
            text = self.big_font.render(msg, True, color)
            self.screen.blit(text, text.get_rect(center=(WIDTH // 2, HEIGHT // 2)))
            sub = self.font.render("Press R to restart, Q to quit", True, WHITE)
            self.screen.blit(sub, sub.get_rect(center=(WIDTH // 2, HEIGHT // 2 + 50)))
        pygame.display.flip()

    def run(self):
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    pygame.quit()
                    sys.exit()
                if event.type == pygame.KEYDOWN and self.state != "play":
                    if event.key == pygame.K_r:
                        self.reset()
                    elif event.key == pygame.K_q:
                        pygame.quit()
                        sys.exit()
            self.update()
            self.draw()
            self.clock.tick(FPS)


if __name__ == "__main__":
    Game().run()
